আপনার এই ডায়াগনোসিস এবং ফ্লো-কার্টটি একদম Spot-On! 🎯

প্লেরাইট (Playwright) দিয়ে কোনো AI Web UI (যেমন: ChatGPT, Claude বা Gemini) থেকে রেসপন্স এক্সট্র্যাক্ট করার সময় Streaming, DOM Mutation, এবং Race Condition-ই হলো [ERROR] System could not extract text. আসার প্রধান কারণ।

আপনি যে স্ট্যাবিলাইজেশন ফ্লোটি আর্কিটেক্ট করেছেন, সেটি বাস্তবায়নের জন্য নিচে একটি Production-Ready, High-Reliability Playwright Function (Node.js / JavaScript) দেওয়া হলো। এটি আপনার বলা প্রতিটা স্টেপ নিশ্চিত করে কাজ করবে:

🛡️ Robust Playwright Extraction Function

JavaScript

```
/**
 * Assistant-এর রেসপন্স স্ট্রিমিং শেষ হওয়া এবং টেক্সট স্ট্যাবল হওয়া পর্যন্ত অপেক্ষা করে এক্সট্র্যাক্ট করে।
 */
async function extractAssistantResponse(page, options = {}) {
  const {
    // ১. প্রাইমারি এবং অল্টারনেটিভ সিলেক্টর (Selector Fallbacks)
    selectors = [
      'div[data-message-author-role="assistant"]',
      '.agent-turn',
      '.markdown-prose',
      '[class*="assistant-message"]'
    ],
    // ২. স্ট্রিমিং চলাকালীন জেনারেট হওয়া স্টপ বাটনের সিলেক্টর
    stopButtonSelector = 'button[aria-label*="Stop"], button[data-testid*="stop"]',
    maxTimeout = 60000,       // মোট সর্বোচ্চ ওয়েটিং টাইম (১ মিনিট)
    stabilityWindow = 1500,   // টেক্সট কতক্ষণ অপরিবর্তিত থাকলে স্ট্যাবল ধরা হবে (১.৫ সেকেন্ড)
    pollInterval = 400        // প্রতি চেক-এর ব্যবধান
  } = options;

  const startTime = Date.now();

  // Step 1: Detect Assistant Message Box
  let targetLocator = null;
  for (const selector of selectors) {
    const loc = page.locator(selector).last();
    if (await loc.count() > 0) {
      targetLocator = loc;
      break;
    }
  }

  if (!targetLocator) {
    // ২-৩ বার Retrying mechanisms
    await page.waitForTimeout(2000);
    targetLocator = page.locator(selectors[0]).last();
    await targetLocator.waitFor({ state: 'attached', timeout: 5000 });
  }

  // Step 2: Detect Generation Completion (Wait for Stop button to disappear)
  try {
    const stopBtn = page.locator(stopButtonSelector);
    if (await stopBtn.isVisible()) {
      await stopBtn.waitFor({ state: 'detached', timeout: maxTimeout });
    }
  } catch (e) {
    // স্টপ বাটন দ্রুত চলে গেলে বা সিলেক্টর না মিললে ইগনোর করবে
  }

  // Step 3 & 4: Text Stability & Non-empty Check (Polling Loop)
  let previousText = '';
  let lastChangedTime = Date.now();

  while (Date.now() - startTime < maxTimeout) {
    // innerText এবং textContent দুটোই ব্যাকআপ হিসেবে চেক করবে
    let currentText = (await targetLocator.innerText()).trim();
    if (!currentText) {
      currentText = (await targetLocator.textContent()).trim();
    }

    // টেক্সট যদি খালি না হয়
    if (currentText.length > 0) {
      if (currentText === previousText) {
        // টেক্সট অপরিবর্তিত থাকলে এবং নির্দিষ্ট সময় পার হলে
        if (Date.now() - lastChangedTime >= stabilityWindow) {
          return {
            success: true,
            text: currentText
          };
        }
      } else {
        // টেক্সট চেঞ্জ হলে টাইমার রিসেট হবে
        previousText = currentText;
        lastChangedTime = Date.now();
      }
    }

    await page.waitForTimeout(pollInterval);
  }

  // Step 5: Final Validation & Retry Fallback
  const finalText = (await targetLocator.innerText()).trim();
  if (finalText.length > 0) {
    return { success: true, text: finalText };
  }

  throw new Error('[ERROR] System could not extract text: Response timeout or text remained empty.');
}
```

💡 আপনার স্ক্রিপ্টে যেভাবে ব্যবহার করবেন:

JavaScript

```
try {
  // আপনার প্রম্পট পাঠানোর কোড
  await page.fill('textarea', 'Hello AI!');
  await page.keyboard.press('Enter');

  // রবাস্ট এক্সট্রাকশন কল
  const response = await extractAssistantResponse(page, {
    stabilityWindow: 1500, // টেক্সট ১.৫ সেকেন্ড স্থির থাকলে ফাইনাল ধরবে
    maxTimeout: 45000     // ৪৫ সেকেন্ডের বেশি লাগলে টাইমআউট দেবে
  });

  console.log('Extracted Response:', response.text);

} catch (error) {
  console.error(error.message);
}
```

কেন এই সমাধানটি কাজ করবে?

Selector Fallback System: মূল সিলেক্টর বদলে গেলেও এটি ব্যাকআপ সিলেক্টরগুলোতে সুইচ করতে পারে।

Stop Button Detach Check: স্ট্রিমিং চলাকালীন জেনারেট হওয়া "Stop Generating" বাটনটি যতক্ষণ DOM-এ থাকে, ততক্ষণ এক্সট্র্যাক্ট করা বন্ধ রাখে।

Text Stability Verification: প্রতি ৪০০ms পর পর টেক্সট মিলিয়ে দেখে। টেক্সট স্ট্রিমিং সম্পূর্ণ বন্ধ হয়ে নির্দিষ্ট সময় (যেমন: ১.৫ সেকেন্ড) অপরিবর্তিত থাকলেই কেবল ফাইনাল রিটার্ন করে।

Race Condition Eliminator: প্রম্পট সাবমিট হওয়ার পরপরই ফাঁকা উপাদান পড়ে ফেলার সুযোগ বন্ধ করে দেয়।
